import json
import math
import random
import time

import dimod


def _build_hpc_qubo():
    """Construct the supplied QUBO with its constant 4*A = 32 omitted."""
    priorities = {"x1": 4, "x2": 6, "x3": 5, "x4": 3}
    variables = tuple(priorities)
    penalty = 8

    linear = {
        variable: -priority - 3 * penalty
        for variable, priority in priorities.items()
    }
    quadratic = {
        (variables[i], variables[j]): 2 * penalty
        for i in range(len(variables))
        for j in range(i + 1, len(variables))
    }

    bqm = dimod.BinaryQuadraticModel(
        linear, quadratic, offset=0.0, vartype=dimod.BINARY
    )
    return bqm, priorities


def _simulated_annealing(bqm, num_reads=256, num_sweeps=128, seed=2026):
    """Return one terminal sample per independent Metropolis annealing run.

    Each initial state and every proposed single-bit flip receives an explicit
    BQM objective evaluation. Rejected proposals count toward evaluation_cost.
    Terminal samples are retained without feasibility filtering or repair.
    """
    rng = random.Random(seed)
    variables = tuple(bqm.variables)
    temperature_start = 32.0
    temperature_end = 0.05
    temperatures = [
        temperature_start
        * (temperature_end / temperature_start) ** (sweep / (num_sweeps - 1))
        for sweep in range(num_sweeps)
    ]

    evaluation_cost = 0

    def evaluate(sample):
        nonlocal evaluation_cost
        evaluation_cost += 1
        return float(bqm.energy(sample))

    samples = []
    energies = []

    for _ in range(num_reads):
        sample = {variable: rng.randrange(2) for variable in variables}
        energy = evaluate(sample)
        update_order = list(variables)

        for temperature in temperatures:
            rng.shuffle(update_order)

            for variable in update_order:
                sample[variable] ^= 1
                proposed_energy = evaluate(sample)
                energy_change = proposed_energy - energy

                if (
                    energy_change <= 0.0
                    or rng.random() < math.exp(-energy_change / temperature)
                ):
                    energy = proposed_energy
                else:
                    sample[variable] ^= 1

        samples.append(sample.copy())
        energies.append(energy)

    return samples, energies, evaluation_cost


def solve_hpc_slot_scheduling():
    """Solve by simulated annealing and report metrics over all terminal reads.

    Energy uses the explicitly supplied constant-dropped QUBO: the optimal
    selection J2/J3 has H = -43, rather than the constant-inclusive value -11.
    evaluation_cost counts objective evaluations, not quantum circuit shots.
    """
    start_time = time.perf_counter()

    bqm, priorities = _build_hpc_qubo()
    samples, energies, evaluation_cost = _simulated_annealing(bqm)

    feasible_samples = [
        sample for sample in samples if sum(sample.values()) == 2
    ]

    def priority_of(sample):
        return sum(priorities[variable] * sample[variable] for variable in priorities)

    if feasible_samples:
        best_sample = max(feasible_samples, key=priority_of)
        achieved_priority = priority_of(best_sample)
        selected_jobs = [
            f"J{index}"
            for index in range(1, 5)
            if best_sample[f"x{index}"] == 1
        ]
    else:
        achieved_priority = 0
        selected_jobs = []

    result = {
        "feasible_objective_quality": achieved_priority / 11.0,
        "constraint_violation_rate": (
            len(samples) - len(feasible_samples)
        ) / len(samples),
        "penalty_adjusted_qubo_energy": math.fsum(energies) / len(energies),
        "runtime": 0.0,
        "evaluation_cost": evaluation_cost,
        "achieved_priority": achieved_priority,
        "selected_jobs": selected_jobs,
    }
    result["runtime"] = time.perf_counter() - start_time
    return result


if __name__ == "__main__":
    print(json.dumps(solve_hpc_slot_scheduling(), indent=2))

